const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫';
let api,demo=false;
const examples=[{id:'DEBT001',title:'Học phí kỳ cuối',category:'Học tập',story:'Khoản học phí còn lại cần hoàn thành để tiếp tục việc học và tốt nghiệp.',amount:14000000,pledged:0,paid:4000000,documents:2,status:'Đang nhận hỗ trợ'}, {id:'DEBT002',title:'Chi phí y tế gia đình',category:'Y tế',story:'Khoản chi phí điều trị phát sinh ngoài dự kiến, cần hỗ trợ thanh toán.',amount:18500000,pledged:0,paid:0,documents:1,status:'Chờ xét duyệt'}];
const icons={wallet:'<rect x="3" y="6" width="17" height="15" rx="2"/><path d="M3 9V5a2 2 0 0 1 2-2h12v3M20 12h-5v5h5M17 14.5h.01"/>',heart:'<path d="M12 7c-4-5-10 1 0 8 10-7 4-13 0-8Z"/><path d="m3 17 3-2 5 3 5-2c3-1 4 1 2 2l-7 4-6-2-2 1"/>',files:'<rect x="4" y="7" width="12" height="14" rx="2"/><path d="M9 7V4a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2h-2"/>',education:'<path d="m2 8 10-5 10 5-10 5L2 8Zm4 3v6c4 4 8 4 12 0v-6M22 8v8"/>',medical:'<path d="M12 21C-7 10 4-3 12 6c8-9 19 4 0 15Z"/><path d="M5 12h4l2-4 3 8 2-4h3"/>',clip:'<path d="M8 10v8a4 4 0 0 0 8 0V6a3 3 0 0 0-6 0v11a1 1 0 0 0 2 0V8"/>'};
const icon=(name)=>`<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.wallet}</svg>`;
export function initDebts(callbacks){api=callbacks;const root=document.createElement('section');root.id='debts-page';root.setAttribute('aria-label','Khoản nợ của tôi');document.body.append(root);root.addEventListener('click',ev=>{const button=ev.target.closest('[data-debt]');if(!button)return;switch(button.dataset.debt){case 'add':demo=false;renderDebts();api.add();break;case 'detail':details(button.dataset.id);break;case 'profile':document.body.classList.remove('debts-mode');api.profile();break;case 'messages':document.body.classList.remove('debts-mode');api.messages();break;case 'back':demo=false;document.body.classList.remove('debts-mode');api.back();break;case 'demo':demo=!demo;renderDebts();break;}});}
export function showDebts(){document.body.classList.remove('onboarding','broke-mode','messages-mode','registration-mode','bros-join-mode','card-wizard-mode');document.body.classList.add('debts-mode');renderDebts();window.scrollTo(0,0);document.querySelector('#debts-title')?.focus({preventScroll:true});}
export function renderDebts(){const root=document.querySelector('#debts-page');if(!root)return;const posts=demo?examples:api.getPosts(),total=posts.reduce((sum,p)=>sum+p.amount,0),paid=demo?4000000:0,pledged=posts.reduce((sum,p)=>sum+(p.pledged||0),0);root.innerHTML=`<div class="debts-shell"><div class="debts-header"><a class="debts-brand" href="#" data-debt="profile"><img src="assets/debtfreelately-mark-clean.png" alt=""><span><strong>DebtFreeLately.</strong><small>BROKE DASHBOARD</small></span></a><div class="debts-header-actions"><button data-debt="profile">Trang cá nhân</button><button data-debt="messages">Tin nhắn</button><span>My Debts</span></div></div><div class="debts-page-heading"><div><h1 id="debts-title" tabindex="-1">My Debts</h1><p>Quản lý khoản nợ và yêu cầu hỗ trợ</p></div><button class="debts-add" data-debt="add"><span>＋</span> Thêm khoản nợ</button></div>${demo?'<div class="debts-demo-notice">ĐANG XEM DỮ LIỆU MẪU · Các số tiền, trạng thái và tài liệu dưới đây chỉ minh họa thiết kế.</div>':''}<div class="debt-statistics"><div>${icon('wallet')}<strong>${money(total)}</strong><span>Tổng khoản nợ</span></div><div>${icon('heart')}<strong>${money(paid)}</strong><span>Đã được giúp ${demo?'· Mẫu':''}</span></div><div>${icon('files')}<strong>${String(posts.length).padStart(2,'0')}</strong><span>Hồ sơ khoản nợ</span></div></div><div class="debts-list-title"><h2>Danh sách khoản nợ</h2><span>${posts.length} hồ sơ</span></div><div class="debts-list">${posts.length?posts.map(p=>card(p,demo)).join(''):`<div class="debts-empty"><div>${icon('wallet')}</div><h3>Một khởi đầu mới, từ đây.</h3><p>Bạn chưa có khoản nợ nào được ghi lại.<br>Thêm khoản nợ đầu tiên để bắt đầu quản lý và chia sẻ câu chuyện.</p><button class="debts-add" data-debt="add">＋ Thêm khoản nợ đầu tiên</button></div>`}</div><div class="debts-bottom"><p>${demo?'Dữ liệu minh họa.':`Dữ liệu lưu trên trình duyệt · ${money(pledged)} cam kết, chưa thanh toán.`}</p><button data-debt="demo">${demo?'← Quay lại khoản nợ của tôi':'Xem giao diện mẫu ↗'}</button></div><button class="debts-back" data-debt="back">← Đổi vai trò</button></div>`;}
function card(p,sample){const paid=sample?(p.paid||0):0,percent=Math.min(100,paid/p.amount*100),label=sample?p.status:'Chưa xác minh',isOpen=sample&&p.status==='Đang nhận hỗ trợ';return `<article class="debt-record"><div class="debt-record-heading"><div class="debt-record-icon">${icon(p.category==='Học tập'?'education':p.category==='Y tế'?'medical':'wallet')}</div><div><h3>${esc(p.title)}</h3><p>${esc(p.category)} · #${sample?p.id:'DEBT-'+esc(p.id.slice(0,8).toUpperCase())}</p></div><span class="debt-status ${isOpen?'open':''}">${esc(label)}</span></div><p class="debt-description">${esc(p.story)}</p><div class="debt-values"><div><small>Số tiền còn nợ ban đầu</small><strong>${money(p.amount)}</strong></div>${paid?`<div><small>Đã hỗ trợ · Mẫu</small><strong>${money(paid)}</strong></div>`:!sample&&p.pledged?`<div><small>Cam kết · Chưa thanh toán</small><strong>${money(p.pledged)}</strong></div>`:''}</div>${isOpen?`<div class="debt-record-progress" role="progressbar" aria-label="Tiến độ hỗ trợ minh họa" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(percent)}"><div style="width:${percent}%"></div></div>`:''}<div class="debt-record-bottom"><span>${icon('clip')}${sample?`${p.documents} tài liệu · Minh họa`:'Chưa có tài liệu đính kèm'}</span><button data-debt="detail" data-id="${esc(p.id)}">Chi tiết →</button></div></article>`;}
function details(id){const p=(demo?examples:api.getPosts()).find(p=>p.id===id);if(!p)return;api.modal(`<div class="eyebrow">${demo?'HỒ SƠ MINH HỌA':'HỒ SƠ KHOẢN NỢ · CHƯA XÁC MINH'}</div><h2>${esc(p.title)}</h2><p>${esc(p.category)}</p><p class="detail-story">${esc(p.story)}</p><div class="info-box">Khoản nợ: <strong>${money(p.amount)}</strong><br>${demo?`Hỗ trợ minh họa: ${money(p.paid||0)}`:`Cam kết: ${money(p.pledged||0)} · Chưa thanh toán`}</div><p>${demo?'Đây là dữ liệu mẫu, không có tiền hoặc tài liệu thật.':'Hồ sơ chỉ lưu trên trình duyệt. Phần nộp và xác minh tài liệu sẽ được bổ sung sau.'}</p>${demo?'':'<button class="dark" id="debt-edit">Chỉnh sửa khoản nợ</button><button class="registration-alt" id="debt-delete">Xóa khoản nợ</button>'}`);if(!demo){document.querySelector('#debt-edit').onclick=()=>{api.close();api.edit(id);};document.querySelector('#debt-delete').onclick=()=>{api.close();api.remove(id);};}}


